package pro.celikom.nativeprobe.identitydiag;
import java.util.*;
import org.json.*;
/** Diagnostic policy: data sources remain explicit; this never authorizes playback. */
final class HybridIdentity {
 static List<String> artists(String s){List<String>a=new ArrayList<>();for(String name:s.split("(?i)[,;]|\\s+(?:feat\\.?|ft\\.?|featuring|&)\\s+")){String n=AlbumMatch.norm(name);if(!n.isEmpty()&&!a.contains(n))a.add(n);}Collections.sort(a);return a;}
 static Map<String,Object> metadata(String title,String artist,long duration,List<Map<String,Object>> rows){LinkedHashMap<String,Object> found=new LinkedHashMap<>();if(AlbumMatch.norm(title).isEmpty()||artists(artist).isEmpty()||duration<=0)return LogStore.map("status","INSUFFICIENT_METADATA","candidates",new ArrayList<>());
  for(Map<String,Object> t:rows){Object len=t.get("durationMs");if(!(len instanceof Number))continue;long ms=((Number)len).longValue();if(ms<=0||Math.abs(ms-duration)>1000)continue;if(!AlbumMatch.norm(title).equals(AlbumMatch.norm(String.valueOf(t.get("displayTitle")))))continue;if(!artists(artist).equals(artists(String.valueOf(t.get("artist")))))continue;Object id=t.get("catalogueTrackId");if(id!=null&&String.valueOf(id).matches("\\d{1,20}"))found.put(String.valueOf(id),t);}
  Map<String,Object> out=LogStore.map("status",found.size()==1?"UNIQUE_METADATA_CANDIDATE":found.isEmpty()?"NO_MATCH":"AMBIGUOUS","candidates",new ArrayList<>(found.values()),"scope","bounded catalogue; uniqueness is not proof of the source edition");if(found.size()==1)out.put("catalogueTrackId",found.keySet().iterator().next());return out;
 }
 static Map<String,Object> own(JSONObject snapshot,String title,String artist,long duration,long now){JSONArray source=snapshot.optJSONArray("tracks");List<Map<String,Object>> rows=new ArrayList<>();if(source!=null)for(int i=0;i<Math.min(source.length(),5000);i++){JSONObject t=source.optJSONObject(i);if(t==null||!t.optBoolean("replacement_available",false))continue;rows.add(LogStore.map("catalogueTrackId",t.optString("track_id"),"displayTitle",t.optString("title"),"artist",t.optString("artist"),"durationMs",t.optLong("duration_ms",-1)));}Map<String,Object> out=metadata(title,artist,duration,rows);long generated=snapshot.optLong("generated_at_ms",0),age=now-generated;boolean fresh=snapshot.optInt("schema")==1&&snapshot.optBoolean("complete",false)&&generated>0&&age>=0&&age<=7*86400000L;out.put("catalogueGeneratedAtMs",generated);out.put("catalogueFreshComplete",fresh);out.put("historicalHintEligible",snapshot.optInt("schema")==1&&snapshot.optBoolean("complete",false)&&generated>0&&age>=0&&"UNIQUE_METADATA_CANDIDATE".equals(out.get("status")));out.put("availableReplacementRows",rows.size());if(!fresh){out.put("candidateStatus",out.get("status"));out.put("status","STALE_OR_INCOMPLETE_SNAPSHOT");}return out;}
 static Map<String,Object> decide(Map<String,Object> primary,Map<String,Object> own,Map<String,Object> learned,boolean pending){String method="NONE",id=null,reason="no_unique_candidate";boolean conflict=false;String primaryStatus=primary==null?"UNAVAILABLE":String.valueOf(primary.get("status"));
  if("UNIQUE_CANDIDATE".equals(primaryStatus)){id=String.valueOf(primary.get("catalogueTrackId"));method="ALBUM";reason="unique_album_candidate";Object weaker=own.get("catalogueTrackId");if(weaker!=null&&!id.equals(weaker)){conflict=true;reason="album_candidate_differs_from_own_catalogue_edition";}}
  else if("AMBIGUOUS".equals(primaryStatus)){reason="album_ambiguous_weaker_fallback_withheld";}
  else if(pending){reason="waiting_for_album_response";}
  else if("UNIQUE_METADATA_CANDIDATE".equals(own.get("status"))){id=String.valueOf(own.get("catalogueTrackId"));method="OWN_CATALOGUE_METADATA";reason="unique_fresh_replacement_metadata_candidate";}
  else if("AMBIGUOUS".equals(own.get("status"))){reason="own_catalogue_ambiguous";}
  else if("UNIQUE_METADATA_CANDIDATE".equals(learned.get("status"))){id=String.valueOf(learned.get("catalogueTrackId"));method="LEARNED_METADATA";reason="unique_candidate_in_previously_received_albums";}
  else if(Boolean.TRUE.equals(own.get("historicalHintEligible"))&&"UNIQUE_METADATA_CANDIDATE".equals(own.get("candidateStatus"))){reason="historical_catalogue_hint_not_used_without_current_identity";}
  return LogStore.map("method",method,"candidateTrackId",id,"reason",reason,"editionConflict",conflict,"automaticSourceIdVerified",false,"replacementStarted",false,"playbackAuthorized",false);
 }
}
